mapper.update:
UPDATE cita
SET
    id_estado_cita = #{idEstadoCita},
    motivo_cancelacion = #{motivo}
WHERE id_cita = #{idCita};

mapper.select:
SELECT COUNT(*)
FROM cita
WHERE id_paciente = #{idPaciente}
  AND fecha = #{fecha}
  AND id_estado_cita IN (2, 4)

      AND id_cita != #{idCita}
  ;

SELECT COUNT(*)
FROM cita
WHERE id_medico = #{idMedico}
  AND fecha = #{fecha}
  AND hora = #{hora}
  AND id_estado_cita IN (2, 4)

      AND id_cita != #{idCita}
  ;

SELECT COUNT(*)
FROM cita
WHERE id_cita = #{value};

SELECT COUNT(*)
FROM paciente
WHERE id_paciente = #{value};

SELECT COUNT(*)
FROM medico
WHERE id_medico = #{value};
